toolCalls.commandLine:
"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command '$ref=(Get-Content -Raw .'"\\REFERENCE_BINARY.txt).Trim(); function RunCap("'$exe,$arglist,$out,$err){ $p=Start-Process -FilePath $exe -ArgumentList $arglist -NoNewWindow -RedirectStandardOutput $out -RedirectStandardError $err -Wait -PassThru; return $p.ExitCode }
$cases=@(
  @('"'headers','tmp\\sel.csv'),@('headers','--just-names','tmp\\sel.csv'),@('count','tmp\\sel.csv'),@('select','h1[1]-h1[0]','tmp\\sel.csv'),@('slice','--start','0','--end','1','tmp\\sel.csv'),@('search','"'^a'"','tmp\\sel.csv'),@('sort','-N','tmp\\sort.csv'),@('fmt','--out-delimiter','\\t','tmp\\fmt.csv'),@('fmt','--quote-always','tmp\\fmt.csv'),@('table','tmp\\fmt.csv'),@('frequency','--limit','0','tmp\\sel.csv'),@('stats','tmp\\sort.csv'))
foreach("'$c in $cases){
  $name=($c -join '"'_') -replace '["'^A-Za-z0-9]'"','_'
  "'$e1=RunCap $ref $c "tmp'"\\r_"'$name.out" "tmp'"\\r_"'$name.err"
  $e2=RunCap '"'.\\executable.cmd' "'$c "tmp'"\\p_"'$name.out" "tmp'"\\p_"'$name.err"
  $b1=[IO.File]::ReadAllBytes((Resolve-Path "tmp'"\\r_"'$name.out")); $b2=[IO.File]::ReadAllBytes((Resolve-Path "tmp'"\\p_"'$name.out"));
  $er1=[IO.File]::ReadAllBytes((Resolve-Path "tmp'"\\r_"'$name.err")); $er2=[IO.File]::ReadAllBytes((Resolve-Path "tmp'"\\p_"'$name.err"));
  $same=($e1 -eq $e2 -and [Convert]::ToBase64String($b1) -eq [Convert]::ToBase64String($b2) -and [Convert]::ToBase64String($er1) -eq [Convert]::ToBase64String($er2))
  if($same){ Write-Output "ok $($c -join '"' ')\" } else { Write-Output \"FAIL "'$($c -join '"' ') exit "'$e1/$e2 len $($b1.Length)/$($b2.Length)"; Write-Output '"'REF:'; Get-Content -Raw \"tmp\\r_"'$name.out"; Write-Output '"'PY:'; Get-Content -Raw \"tmp\\p_"'$name.out"; Write-Output '"'ERR REF/PY'; Get-Content -Raw \"tmp\\r_"'$name.err"; Get-Content -Raw "tmp'"\\p_"'$name.err" }
}'

